from typing import Dict, List, Optional, Tuple
Pos = Tuple[int, int]
PartialDB = Dict[Pos, Optional[int]]

def get(db: PartialDB, p: Pos) -> Optional[int]:
    return db.get(p, None)

def consistent_pair(a: PartialDB, b: PartialDB, ps: List[Pos]) -> bool:
    return all(not (get(a,p) is not None and get(b,p) is not None and get(a,p) != get(b,p)) for p in ps)

def sheaf_condition(dbs: List[PartialDB], ps: List[Pos]) -> bool:
    return all(consistent_pair(dbs[i], dbs[j], ps) for i in range(len(dbs)) for j in range(len(dbs)))

def coboundary_norm(dbs: List[PartialDB], ps: List[Pos]) -> int:
    return sum(1 for i in range(len(dbs)) for j in range(len(dbs)) for p in ps
               if get(dbs[i],p) is not None and get(dbs[j],p) is not None and get(dbs[i],p) != get(dbs[j],p))

ps: List[Pos] = [(r,c) for r in range(2) for c in range(2)]
consistent = [
    {(0,0):5,(1,0):7}, {(0,0):5,(0,1):3}, {(0,1):3,(1,0):7,(1,1):9},
]
conflicting = [
    {(0,0):5,(1,0):7}, {(0,0):5,(0,1):3}, {(0,1):99,(1,0):7,(1,1):9},
]
for name, fam in [("consistent", consistent), ("conflicting", conflicting)]:
    norm = coboundary_norm(fam, ps)
    sheaf = sheaf_condition(fam, ps)
    assert (norm == 0) == sheaf
    print(f"{name:11s}: coboundary norm = {norm}, sheaf_condition = {sheaf}")
print("coboundary_zero_iff_sheaf verified.")

from typing import Dict, List, Optional, Tuple
Pos = Tuple[int, int]
PartialDB = Dict[Pos, Optional[int]]

def get(db: PartialDB, p: Pos) -> Optional[int]:
    return db.get(p, None)

def imputation_objective(observed: PartialDB, cand: Dict[Pos, int], ps: List[Pos]) -> int:
    return sum(1 for p in ps if get(observed,p) is not None and get(observed,p) != cand[p])

ps: List[Pos] = [(r,c) for r in range(2) for c in range(3)]
observed: PartialDB = {(0,0):5,(0,2):2,(1,1):8}
faithful = {(0,0):5,(0,1):0,(0,2):2,(1,0):1,(1,1):8,(1,2):9}
wrong    = {(0,0):5,(0,1):0,(0,2):7,(1,0):1,(1,1):8,(1,2):9}
for name, cand in [("faithful", faithful), ("wrong", wrong)]:
    cost = imputation_objective(observed, cand, ps)
    extends = all(cand[p] == get(observed,p) for p in ps if get(observed,p) is not None)
    assert (cost == 0) == extends
    print(f"{name:9s}: objective = {cost}, extends_data = {extends}")
print("imputation_zero_iff_extends verified.")

