function CoboundaryConsistency(dbs, positions):
    norm <- 0; conflicts <- []
    for i in 0..n-1:
        for j in 0..n-1:
            for p in positions:
                vi <- dbs[i][p]; vj <- dbs[j][p]
                if vi != MISSING and vj != MISSING and vi != vj:
                    norm <- norm + 1
                    conflicts.append((i, j, p, vi, vj))
    return (norm == 0, norm, conflicts)   // sheaf condition holds iff norm == 0

