function IteratedGlue(dbs, positions):
    assert CoboundaryConsistency(dbs, positions).holds
    glued <- empty database
    for db in dbs:
        for p in positions:
            if glued[p] == MISSING:
                glued[p] <- db[p]   // prefer existing accumulated value
    return glued

