function NearestGlobalSectionImpute(observed, positions, estimator):
    candidate <- {}
    for p in positions:
        if observed[p] != MISSING:
            candidate[p] <- observed[p]      // faithful: zero objective
        else:
            candidate[p] <- estimator(p, observed)
    return candidate                          // SheafImputationObjective == 0
